test("entry date scenario 1", { tag: '@functionality' }, async ({ browser }) => {
  const sheet = ui.sheetId();
  const pg_uma = await ui.userPage(browser, "uma", sheet);
  await ui.setToday(pg_uma, "2026-03-10");
  expect(await ui.setRole(pg_uma, "wes", "steward")).toBe(true);
  await ui.setSetting(pg_uma, "clerk-limit", "3.00");
  await ui.setSetting(pg_uma, "floor", "0.50");
  await ui.setSetting(pg_uma, "terms", "10");
  await ui.setSetting(pg_uma, "late-pct", "5.00");
  await ui.setSetting(pg_uma, "period-numbering-from", "2026-03-01");
  await ui.setSetting(pg_uma, "cap", "5.00");
  await ui.setSetting(pg_uma, "proof-threshold", "1.00");
  expect(await ui.setRole(pg_uma, "vic", "viewer")).toBe(true);
  await ui.setSetting(pg_uma, "entry-date", "2026-03-05");
  expect(await ui.setRate(pg_uma, {"grade": "A", "pct": "33.33"})).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "B", "pct": "5.00"})).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "C", "pct": "12.50", "from": "2026-03-16"})).toBe(true);
  expect(await ui.addPeriod(pg_uma, {"name": "P1", "from": "2026-03-01", "to": "2026-03-15"})).toBe(true);
  const p_ben = ui.must(await ui.addPerson(pg_uma, {"name": "Ben", "grade": "C"}));
  const p_cam = ui.must(await ui.addPerson(pg_uma, {"name": "Cam", "grade": "C"}));
  expect(await ui.statementAsOf(pg_uma, p_ben, "2026-03-20")).toBe(false);
  const c_ben_0 = ui.must(await ui.addClaimTwice(pg_uma, p_ben, {"amount": "7.77", "date": "2026-03-09"}));
  expect(await ui.claimCount(pg_uma, p_ben)).toBe(1);
  await ui.setToday(pg_uma, "2026-03-21");
  const c_cam_0 = ui.must(await ui.addClaim(pg_uma, p_cam, {"amount": "12.50", "date": "2026-04-02"}));
  await ui.setSetting(pg_uma, "late-pct", "5.00");
  const pg_vic = await ui.userPage(browser, "vic", sheet);
  expect(await ui.retire(pg_vic, p_cam, "2026-04-02")).toBe(false);
  await ui.showRetired(pg_vic, true);
  await ui.refresh(pg_vic);
  expect(await ui.claimAction(pg_vic, c_ben_0, "open")).toBe(false);
  expect(await ui.watch(pg_vic, p_cam, true)).toBe(false);
  expect(await ui.setSettingDated(pg_vic, "late-pct", "0.00", "2026-03-15", "5.00")).toBe(false);
  expect(await ui.claimAction(pg_vic, c_ben_0, "open")).toBe(false);
  expect(await ui.claimEditOpen(pg_vic, c_ben_0)).toBe(false);
  const pg_wes = await ui.userPage(browser, "wes", sheet);
  expect(await ui.claimEditOpen(pg_wes, c_ben_0)).toBe(true);
  await ui.refresh(pg_vic);
  expect(await ui.bulkGrade(pg_vic, [p_ben, p_cam], {"grade": "C"})).toBe(0);
  expect(await ui.setRate(pg_vic, {"grade": "C", "pct": "20.00"})).toBe(false);
  await ui.refresh(pg_vic);
  expect(await ui.setSettingTry(pg_vic, "entry-date", "")).toBe(false);
  expect(await ui.addClaim(pg_vic, p_cam, {"amount": "0.04", "date": "2026-03-09"})).toBeNull();
  expect(await ui.claimAction(pg_vic, c_cam_0, "open")).toBe(false);
  expect(await ui.periodAction(pg_vic, "P1", "close")).toBe(false);
  expect(await ui.addClaim(pg_vic, p_ben, {"amount": "3.33", "date": "2026-02-10", "note": "n"})).toBeNull();
  expect(await ui.periodAction(pg_vic, "P1", "close")).toBe(false);
  expect(await ui.retire(pg_vic, p_ben, "2026-02-10")).toBe(false);
  await ui.refresh(pg_vic);

